Matching Ayahs
- = Alif, Lam, Mim. 2:1; 3:1; 29:1; 30:1; 31:1; 32:1
- = Ava vari panzira yakatwasuka kubva kuna Tenzi wavo, uye ava ndivo vanobudirira. 2:5; 31:5
- = Imi vana vaIsraeri, rangarirai nyasha Dzangu dzandakakupai uye kuti ndakakusarudzai pamusoro penyika (vanhu). 2:47; 2:122
- = Iri raiva rudzi rwakapfuura. Rine zvakawana, uye imi mune zvamakawana. Uye hamuzobvunzwa pamusoro pezvavaiita. 2:134; 2:141
- = Vachagara mariri nekusingaperi. Chirango hachizorerutswa kwavari, uye havazombopiwi nguva. 2:162; 3:88
