- = Vakati: "Isu tatenda muna Tenzi wenyika." 7:121; 26:47
- = Tenzi waMoses naAroni. 7:122; 26:48
- = Uye Ini ndichavapa nguva. Zvirokwazvo, zano Rangu rakasimba. 7:183; 68:45
